import React from "react";
import { useDispatch, useSelector } from "react-redux";
import { increment, decrement } from "../redux/slices/CounterSlice";

const Counter = () => {
  // Accessing state and dispatch from redux store coz hme count ki value chaiye wo CounterSlice me store hai
  const count = useSelector((state) => state.counter.value);
  //dispatch krne k liye
  const dispatch = useDispatch();

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-r from-indigo-700 via-purple-600 to-pink-500 p-6">
      {/* Increment and Decrement ko export kiye the store se toh yha usko use kiya with a dispatch function */}
      <button
        className="px-6 py-3 bg-white/90 text-indigo-700 font-semibold rounded-lg shadow-lg hover:scale-105 transform transition py-2"
        onClick={() => dispatch(increment())}
      >
        Increment
      </button>
      <br />
      <br />

      <div className="text-5xl font-extrabold text-white tracking-tight drop-shadow-lg">
        {count}
      </div>

      <br />
      <br />

      <button
        className="px-6 py-3 bg-white/90 text-indigo-700 font-semibold rounded-lg shadow-lg hover:scale-95 transform transition"
        onClick={() => dispatch(decrement())}
      >
        Decrement
      </button>
    </div>
  );
};

export default Counter;
